package com.fullstack.exp232.security;
import org.springframework.stereotype.Service; import javax.crypto.Cipher; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.Base64;
@Service public class AesEncryptionService {private static final byte[] KEY="Exp232-AES-Secret-Key-2026-32B!!".getBytes(StandardCharsets.UTF_8); public String encrypt(String s){try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(KEY,"AES"),new GCMParameterSpec(128,iv));byte[] e=c.doFinal(s.getBytes(StandardCharsets.UTF_8));byte[] r=new byte[12+e.length];System.arraycopy(iv,0,r,0,12);System.arraycopy(e,0,r,12,e.length);return Base64.getEncoder().encodeToString(r);}catch(Exception e){throw new IllegalStateException(e);}} public String decrypt(String s){try{byte[] a=Base64.getDecoder().decode(s);byte[] iv=java.util.Arrays.copyOfRange(a,0,12);byte[] e=java.util.Arrays.copyOfRange(a,12,a.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(KEY,"AES"),new GCMParameterSpec(128,iv));return new String(c.doFinal(e),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException(e);}}}
